export type GalaxyConfig={galaxyRadius:number;galaxyThickness:number;spiralTightness:number;armCount:number;armWidth:number;randomness:number;rotationSpeed:number};export const DEFAULT_WEBGPU_GALAXY_CONFIG:GalaxyConfig={galaxyRadius:20,galaxyThickness:4.2,spiralTightness:1.25,armCount:4,armWidth:5.2,randomness:1.10,rotationSpeed:.05};export function webgpuGalaxyHash(seed:number){const f=(v:number)=>v-Math.floor(v),p=f(seed*.1031),h=p+19.19;return f(h*(h+47.43)*p)}export function generateSpiralPosition(index:number,c:GalaxyConfig,seedOffset=0){const seed=index+seedOffset,r=Math.pow(webgpuGalaxyHash(seed+1),.5)*c.galaxyRadius,n=r/c.galaxyRadius,arm=Math.floor(webgpuGalaxyHash(seed+2)*c.armCount),aa=arm*6.28318/c.armCount,sa=n*c.spiralTightness*6.28318,ao=(webgpuGalaxyHash(seed+3)-.5)*c.randomness,ro=(webgpuGalaxyHash(seed+4)-.5)*c.armWidth,a=aa+sa+ao,rr=r+ro,tf=1-n+.2,x=Math.cos(a)*rr,z=Math.sin(a)*rr,y=(webgpuGalaxyHash(seed+5)-.5)*c.galaxyThickness*tf,rs=Math.abs(ro)/(c.armWidth*.5+.01),as=Math.abs(ao)/(c.randomness*.5+.01),s=Math.min(1,(rs+as)*.5),os=1/(rr+.5)*5;return{position:[x,y,z]as[number,number,number],normalizedRadius:n,angle:a,sparsityFactor:s,orbitalVelocity:[-Math.sin(a)*os,0,Math.cos(a)*os]as[number,number,number]}}export function generateCloudPosition(index:number,c:GalaxyConfig){const seed=index+10000,r=Math.pow(webgpuGalaxyHash(seed+1),.7)*c.galaxyRadius,n=r/c.galaxyRadius,arm=Math.floor(webgpuGalaxyHash(seed+2)*c.armCount),aa=arm*6.28318/c.armCount,sa=n*c.spiralTightness*6.28318,ao=(webgpuGalaxyHash(seed+3)-.5)*c.randomness,ro=(webgpuGalaxyHash(seed+4)-.5)*c.armWidth,a=aa+sa+ao,rr=r+ro,tf=1-n+.15;return{position:[Math.cos(a)*rr,(webgpuGalaxyHash(seed+5)-.5)*c.galaxyThickness*tf,Math.sin(a)*rr]as[number,number,number],normalizedRadius:n,size:(webgpuGalaxyHash(seed+6)*.5+.7)*(1-n*.5),rotation:webgpuGalaxyHash(seed+7)*6.28318}}export function applyDifferentialRotation(position:[number,number,number],speed:number,dt:number):[number,number,number]{const[x,y,z]=position,d=Math.hypot(x,z),f=1/(d*.1+1),a=-speed*f*dt,c=Math.cos(a),s=Math.sin(a);return[x*c-z*s,y,x*s+z*c]}
